import{_ as i,o as a,c as t,ae as l}from"./chunks/framework.DCJ5T8RY.js";const u=JSON.parse('{"title":"响应式图片优化","description":"","frontmatter":{"title":"响应式图片优化","date":"2020-04-12"},"headers":[],"relativePath":"2020/responsive-image-optimization.md","filePath":"2020/responsive-image-optimization.md","lastUpdated":1786185344000}'),o={name:"2020/responsive-image-optimization.md"};function r(s,e,n,p,c,d){return a(),t("div",null,[...e[0]||(e[0]=[l('<h3 id="写在前面" tabindex="-1">写在前面 <a class="header-anchor" href="#写在前面" aria-label="Permalink to &quot;写在前面&quot;">​</a></h3><blockquote><p>图片消耗了网页流量的50%（中位数），移动端图片消耗了大约900Kb</p><p>​ - httparchive.org, 2020.01</p></blockquote><h3 id="图片优化的2个目标" tabindex="-1">图片优化的2个目标 <a class="header-anchor" href="#图片优化的2个目标" aria-label="Permalink to &quot;图片优化的2个目标&quot;">​</a></h3><ul><li>保持图片质量的同时，减少不必要的流量（为了更快的加载）</li><li>没有页面布局抖动（为了更好的体验）</li></ul><h3 id="如何做" tabindex="-1">如何做 <a class="header-anchor" href="#如何做" aria-label="Permalink to &quot;如何做&quot;">​</a></h3><ol><li><p>图片格式</p><ul><li>绝大多数情况使用jpg</li><li>少数有透明背景要求的情况使用png</li><li>gif尽量不用，使用短视频替换</li><li>尽量使用新格式webp，可以大幅缩小图片体积</li></ul></li><li><p>响应式</p><ul><li>img标签使用src-set，sizes适配不同尺寸</li><li>多种格式可以使用picture元素，通过source属性指定不同格式图片</li></ul></li></ol>',6)])])}const _=i(o,[["render",r]]);export{u as __pageData,_ as default};
